  "track.fp.vz.persist.ref.booked": "the booked list",
  "track.fp.vz.persist.ref.selected": "Cons(b4, booked): one new node and the old tail",
  "track.fp.vz.persist.ref.alias": "the same object as booked",
  "track.fp.vz.persist.ref.tail": "selected.tail: booked itself",
  "track.fp.vz.persist.rec.plain": "plain recursion",
  "track.fp.vz.persist.rec.tailrec": "accumulator + tailrec",
